raw:
{
"장르": "액션, 캐주얼",
"핵심플레이": "SPY Fox의 M.E.S.S.를 통해 토마토 저장과 왕좌 정복을 위한 액션 게임 플레이",
"특징": "아동용 어드벤처 게임으로, 5세부터 10세까지의 어린이와 성인 모두에게 적합"
}

{
"장르": "Strategy, Casual, Indie",
"핵심플레이": "플레이어들은 배를 이끌고 상대방 배를 공격하며 전략적으로 배치하고 대응한다.",
"특징": "무작위 이벤트로 전통적인 게임 동력이 변화되며, 난세와 상황변화에 따라 전략을 재정의해야 한다."
}

{
    "장르": "Adventure, Casual, Simulation",
    "핵심플레이": "유저는 친구들이 갑작스럽게 집에 들어와 함께 생활하면서 벌어지는 일들을 경험하며 이야기를 진행한다.",
    "특징": "가족 관계와 도시 생활의 어려움, 그리고 불청객과의 대치 상황 등 다양한 캐릭터와 상황을 통해 재미있는 이야기를 전개한다."
}

{
"장르": "액션, 인디",
"핵심플레이": "과학자가 시간 여행을 통해 과거로 돌아가 자신의 꿈을 이룰 수 있도록 도와야 한다. 하지만 과거 현실과 달리 위험한 상황에 직면하게 된다.",
"특징": "16개의 독특한 장소를 통해 과학자를 이끌어야 하며, 난관을 극복하고 몬스터와의 대결, 퍼즐 해결 등을 통해 레벨을 완료해야 한다."
}

{
"장르": "Adventure, Indie, RPG",
"핵심플레이": "마린과 친구들이 6일 안에 남은 네 명의 전사들을 찾고 대결을 가는 모험을 즐긴다.",
"특징": "40개 이상의 성취, 4단계의 난이도 선택, 보이거나 숨겨진 몬스터 선택, 애니메이션 효과와 음악, 25개 이상의 미션, 9개의 동물 왕을 상대하는 전투, 마릴레이는 필요할 때마다 도움을 청할 수 있는 마법사 친구 등"
}

{
"장르": "퍼즐, casual",
"핵심플레이": "연결된 같은 색상의 끈을 연결하면 그 끈이 사라지고 게임판이 조금씩 재배열된다.",
"특징": "특별한 규칙은 플레이어의 판단과 전망력을 시험하며, 오류를 인정하고 배우며 점진적으로 개선할 수 있는 게임이다."
}

{
    "장르": "Point&Click comedy adventure, Casual, Indie",
    "핵심플레이": "점프 액션과 비디오 게임 유니버스를 탐험하며 농담과 상상력을 요구하는 레이블링을 해결하는 플레이",
    "특징": "비현실적인 3D 그래픽, 거의 완벽하게 녹음된 대본, 'Out of the Box' 문제 해결, 부트업 시스템, 몇몇 외국 발음의 존재, 몇몇 버그 포함"
}

{
    "장르": "Indie, RPG",
    "핵심플레이": "플레이어는 전설적인 술집을 재창조하려고 하지만, 그 과정에서 비극과 감정적 갈등을 겪으며 성장한다.",
    "특징": "30개의 독립적 발전 끝나는 결말, 5개의 전체 음성 줄, 30개 이상의 아름다운 CG, 20개 이상의 아름다운 음악, 다양한 주인공 선택, 70여 가지의 음식과小吃, 50개 이상의 주인공과의 대화 주제"
}

{
"장르": "액션, 인디, 이어디즈 아크",
"핵심플레이": "단일 플레이에서는 벌레를 잡아 점수를 얻고, 최소 500점 이상을 얻어야 랭킹을 유지할 수 있으며, 100벌레를 한 번에 수집하면 보너스 점수를 받습니다. 멀티플레이에서는 친구들과 대결하거나 협력하여 벌레를 잡는 것이 목표입니다.",
"특징": "세 가지 무기 시스템이 포함되어 있습니다: 주요 공격은 기계식 총, 중량형 공격은 자동화된 홈링 미사일 발사기, 상황에 따라 사용되는 후방 폭탄. 게임은 첫 번째 사람 모드와 세 번째 사람 모드에서 플레이가 가능합니다."
}

{
"장르": "액션, 액션-platformer",
"핵심플레이": "스파트라쿠스가 빠른 스피드와 다양한 무기 사용을 통해 러시아의 군대와 싸운다.",
"특징": " retro 플레이어 패널티 없이 자유롭게 이동하며 다양한 적과 싸우며, 빛나는复古像素艺术风格, 다양한 무기와 능력치 업그레이드"
}

{
"장르": "액션, 스토리텔링",
"핵심플레이": "사용자는 인공위성에 위치한 큰 파란 달을 중심으로 한 아름다운 세계를 탐험하며 이야기를 진행하고, 주변을 조사하고 새로운 미션 라인을 찾아야 한다.",
"특징": "사용자의 각 행동을 고려하고 해결해야 하는 수수께끼를 통해 새로운 이야기의 부분을 열고, 긴급한 결말을 찾는다."
}

{
"장르": "액션, 인디, RPG",
"핵심플레이": "마법 땅으로의 포탈이 열리면서 전투 중인 적들을 수집하거나 잡아서 스피릿으로 변환하고, 이를 통해 다양한 조합을 만들어 강화하거나 새로운 스토리를 구성할 수 있다.",
"특징": "강력한 유니크 스피릿은 독특한 성격과 스토리가 있으며, 다른 스피릿을 잡아吸收하여 능력을 얻을 수 있다. 점&クリック 인벤토리와 해결 가능한 점&클릭 어itic스가 있으며, RPG 특성상 다양한 방법으로 해결할 수 있다."
}

{
"장르": "Simulation, Strategy",
"핵심플레이": "Darwin's Aquarium은 실시간 물고기 번식 시뮬레이션 게임으로, 자신의 물고기를 키우고 훈련하여 생존과 성장에 도달시키는 것을 목표로 한다.",
"특징": "물고기와의 상호작용이 다양하며, 일부 물고기는 알미를 재배하거나 적대적인 물고기를 유혹하는 기술을 배울 수 있다. 게임은 진화론적 생태계를 재현하려는 목표를 가지고 있으며, 플레이어는 다른 플레이어와 협력하거나 대결할 수 있다."
}

{
"장르": "Casual, 리ラク제스",
"핵심플레이": "재생중인 음악을 선택하고 다양한 환경에서 자유롭게 움직이며 리ラク제스를 즐긴다.",
"특징": "스페이스와 그린 오아시스의 아름다운 시공간을 통해 감각적인 음악과 함께 여행하며 마음을 진정시킨다."
}

{
"장르": "액션, RPG",
"핵심플레이": "프롤로그에서의 재회와 그로 인한 이야기 진행, 생활 관리와 상황 해결",
"특징": "평화로운 섬 생활에서 벗어나는 재미있는 모험, 친구와의 관계 형성, 비밀 파헤치기"
}

{
    "장르": "Hidden Object, Indie",
    "핵심플레이": "유저가 각 레벨에서 모든 팬더와 메추라기를 찾아야 한다.",
    "특징": "15개의 작품에서 총 1500개 이상의 숨겨진 객체를 찾고, 무한히 사용 가능한 도움말 기능을 갖춘 게임"
}

{
    "장르": "액션, 액션adventure, 인디",
    "핵심플레이": "Frebb과 동료들이 무대 위에서 끊임없이 움직이며, 다양한 기술을 사용해 플랫폼을 타고 이동하며 액션을 즐긴다.",
    "특징": "다양한 패턴을 활용한 속도감 있는 플랫폼 게임, 네 가지 주인공 각각 독특한 기술과 행동을 가진다, 간단하지만 만족스러운 전투, 복잡하고 변화하는 대결 상대, 아름다운 환경과 감성적인 캐릭터 설정, 유쾌하고 재미있는 이야기와 미묘한 캐릭터 설정"
}

{
"장르": "Adventure, Casual",
"핵심플레이": "플레이어와 카풀 운전사인 닉이 함께 도시의 필요로운 사람들과 함께 일정을 진행하며 크리스마스의 진정한 의미를 찾는다.",
"특징": "숨겨진 객체 찾기 액션 어드벤처 게임으로, 크리스마스 시즌을 배경으로 한 판타지 세계에서 플레이어가 주인공의 이야기를 따라간다."
}

{
"장르": "Casual, Indie, Simulation",
"핵심플레이": "Milly가 자연 속에서 자유롭게 이동하며, 간단한 자연의 소리와 활동을 감상하는 게임",
"특징": "무언가를 수행하거나 압박받지 않는 편안한 환경에서 자연의 풍경과 음악을 즐길 수 있는 게임"
}

{
    "장르": "Casual, Indie",
    "핵심플레이": "게임은 터틀 호날두 유형의 퍼즐에서 규칙을 따르며, 큰 돌은 작은 돌 위에 올 수 없습니다. 각 움직임마다 돌은 시계 방향으로 회전하여 패턴이 변합니다.",
    "특징": "50개의 깊게 디자인된 레벨, 스ynth웨이 클래식과 일부 카이퍼punk 요소를 기반으로 한 원시 음악, 편안한 플레이어 게임, 아름다운 미래 스타일의 그래픽"
}

{
"장르": "Adventure, Casual, Indie",
"핵심플레이": "유저가 7명의 주인공을 선택하여 그들의 선택과 그 결과를 경험하며 진행되는 비디오 노벨 스토리",
"특징": "별세계를 배경으로 한 액션과 감정적인 이야기, 다양한 캐릭터와 그들의 관계, 그리고 결정론적인 선택들에 따른 결과"
}

{
"장르": "Indie, RPG, Simulation",
"핵심플레이": "여성캐릭터와의 로맨틱한 모험을 통해 다양한 무기를 수집하고 액션 치트 던전을 해결한다.",
"특징": "다양한 무기 스타일과 캐릭터의 성별 및性別에 따른 성적 표현이 포함되어 있다."
}

{
    "장르": "Simulation, Strategy",
    "핵심플레이": "데이터 센터 운영과 건설을 관리하며, 재난 대응 및 시스템 확장에 대한 전략적 결정을 내린다.",
    "특징": "다양한 데이터 센터 시스템 구축과 운영, 예산 제약, 하드웨어 변경 등 실제 클라우드 환경에서의 문제 해결을 다룬다."
}

{
"장르": "Simulation, Sports",
"핵심플레이": "Rezzil Player는 다양한 스포츠의 기술과 반응 시간을 향상시키는 게임으로, 160개의 레벨과 40개의 스포츠 액세서리를 포함한 세계 최고의 스포츠 앱입니다.",
"특징": "Headers, Hoops Vision, Reaction Wall, Pocket Slide, Shot Stopper 등 다양한 스포츠 트레이닝 게임으로 구성되어 있으며, 각 게임은 실제 경기에 적용할 수 있는 실용적인 기술을 향상시킵니다."
}

{
"장르": "Simulation, Strategy",
"핵심플레이": "회사의 최고 경영자로서 다양한 산업 분야에서 중요한 경영 결정을 내리고, 제품 산업 체인을 계획하고 최적화하며, 기술 연구와 개발을 통해 품질 제고를 목표로 한다.",
"특징": "재무적 의사결정을 포함한 모든 영역에서 중요한 경영 결정을 내리고, 다양한 제품 유형을 사용하여 산업 체인을 구축하고, 다른 상장 회사의 도전에 대응하거나 주식 거래를 통해 급성장 또는 장기 투자를 실현할 수 있다."
}

{
"장르": "퍼즐, casual",
"핵심플레이": "스페이스 로직을 사용해 흐트러진 텔레트를 이용해 햇빛을 흑홀 위에 고정시킨다.",
"특징": "새로운 모드와 퍼즐 패ck을 추가했으며, 재미있는 새로운 플레이 방식을 제공한다."
}

{
"장르": "Casual, Match-3",
"핵심플레이": "게스트가 시즌을 복원하며, Match-3 기술을 사용하여 여름, 겨울, 봄, 가을의 문제를 해결한다.",
"특징": "타임 모드와 이동 횟수 제한 모드를 포함한 다양한 플레이 모드가 있으며, 게임 중에 모드를 변경할 수 있다."
}

{
"장르": "RPG, 성적 변형, 성적 모욕",
"핵심플레이": "전투 시 몸부림치는 적의 몸부분을 변형하여 자신에게 맞추고 이를 통해 전략을 변경하거나 빙의된 퍼포먼스를 사용하여 전투를 이겨나간다.",
"특징": "변형을 통해 전투 전략을 조정하고, 다양한 방식으로 전투를 해결하며, 불편한 상황에서도 성적인 퍼포먼스를 활용하여 승리를 거두는 등 성적 모욕과 변형을 통한 전투가 주요 요소이다."
}

{
"장르": "Simulation, Sports",
"핵심플레이": "Custom-built runs, gnarly tricks, and real-world competitions in a procedurally generated mountain environment.",
"특징": "Enhanced editor for creating custom parks, authentic snowboarding physics, procedural generation of mountains, and online sharing of course creations."
}

{
"장르": "액션, 레이싱",
"핵심플레이": "무인 승객이 폭격으로 파괴된 집의 잔해에서 꽃으로 변신하여 다른 잠재된 영혼들을 구해내고, 그들의 길을 이끄는 플레이를 통해 영혼을 천국의 문으로 이끌어나가는 경쟁",
"특징": "별세계적인 시각효과, 음악은 유명 프로듀서가 만든 딥 파시트 뮤직트랙, 비행 플레이가 전환되는 동적인 전지역 무한 생성 환경"
}

{
"장르": "Adventure, Platform",
"핵심플레이": "재생된 캐릭터의 움직임을 기록하고, 리모컨을 사용해 시간을 조작하여 캐릭터들의 행동을 재조합한다.",
"특징": "픽셀 아트 스타일과 변화하는 게임 플레이, 4개의 영화 기반 세계에서 약 70개의 레벨, 각 레벨마다 기록을 깨는 목표와 추가적인 목표"
}

